export class TarefasMobilePage11Listas_tarefasPage extends TarefasListas_tarefasShared {
  private msg: PageMessageType = pageMessage_pt_br;

  private renderCollection() {
    const items = this.listas?.items ?? [];
    const hasSearch = this.texto !== null && this.texto !== '';
    const hasPreconditionError = this.qryListasTarefasError?.code === 'client.preconditionMissing';

    return html`
      <section data-organism-id="listasCadastradas" class="flex min-h-full flex-col gap-5 bg-[var(--page-bg,transparent)] px-4 py-5">
        <div class="flex items-end gap-3">
          <groupsearchcontent--ml-search-bar
            class="min-w-0 flex-1"
            .value=${this.texto}
            .name=${'busca-listas'}
            .placeholder=${this.msg.searchPlaceholder}
            .debounce=${300}
            .loading=${this.qryListasTarefasStatus === 'loading'}
            @search=${(e: CustomEvent<{ query: string }>) => this.qryListasTarefas(e.detail.query || null)}
            @clear=${() => this.qryListasTarefas(null)}>
            <Label>${this.msg.searchLabel}</Label>
          </groupsearchcontent--ml-search-bar>
          <grouptriggeraction--ml-button-standard
            data-variant="secondary"
            size="md"
            data-class="shrink-0"
            @action=${() => {
              this.selectListaTarefas(null);
              this.setScenario('nova');
            }}>
            <Label>${this.msg.newList}</Label>
          </grouptriggeraction--ml-button-standard>
        </div>

        ${this.qryListasTarefasStatus === 'error' ? html`
          <groupnotifyuser--ml-contextual-feedback
            type="error"
            .visible=${true}
            .dismissible=${false}
            .duration=${0}>
            <Title>${hasPreconditionError ? this.msg.missingContextTitle : this.msg.loadErrorTitle}</Title>
            <Message>${hasPreconditionError ? this.msg.missingContextMessage : this.msg.loadErrorMessage}</Message>
            <Action>
              <button
                type="button"
                class="min-h-11 font-medium text-[var(--link-text,currentColor)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]"
                @click=${() => this.qryListasTarefas(this.texto)}>
                ${this.msg.retryLoad}
              </button>
            </Action>
          </groupnotifyuser--ml-contextual-feedback>
        ` : ''}

        <groupviewdata--ml-vertical-record-list
          data-class="w-full overflow-hidden rounded-xl border border-[var(--border-subtle,currentColor)] bg-[var(--surface-bg,transparent)]"
          .loading=${this.qryListasTarefasStatus === 'loading'}
          .hoverable=${true}
          @row-click=${(e: CustomEvent<{ index: number }>) => {
            const lista = items[e.detail.index];
            if (lista) {
              this.selectListaTarefas(lista.id);
              this.setScenario('editar');
            }
          }}>
          <Columns>
            <Column field="nome" header=${this.msg.listName}></Column>
            <Column field="tarefas-abertas" header=${this.msg.openTasks}></Column>
          </Columns>
          <Rows>
            ${items.map((lista) => html`
              <Row ?selected=${lista.id === this.selectedListaTarefas} data-class="min-h-16">
                <Cell data-class="min-w-0">
                  <span class="block truncate text-base font-semibold text-[var(--text-strong,currentColor)]">${lista.nome}</span>
