            data-class="w-full"
            .value=${draft.nome ?? ''}
            .error=${failed ? this.msg.nameError : ''}
            .name=${'nome'}
            .placeholder=${this.msg.namePlaceholder}
            .minLength=${4}
            .maxLength=${null}
            .required=${true}
            .loading=${submitting}
            @input=${(e: CustomEvent<{ value: string }>) => this.setCmdCriarListaDraft({ ...draft, nome: e.detail.value || null })}>
            <Label>${this.msg.nameLabel}</Label>
            <Helper>${this.msg.nameHelper}</Helper>
          </groupentertext--ml-floating-text-input>

          <groupentertext--ml-multiline-text
            data-class="w-full"
            .value=${draft.details.descricao ?? ''}
            .name=${'descricao'}
            .placeholder=${this.msg.descriptionPlaceholder}
            .rows=${4}
            .maxLength=${null}
            .loading=${submitting}
            @input=${(e: CustomEvent<{ value: string }>) => this.setCmdCriarListaDraft({ ...draft, details: { ...draft.details, descricao: e.detail.value || null } })}>
            <Label>${this.msg.descriptionLabel}</Label>
            <Helper>${this.msg.descriptionHelper}</Helper>
          </groupentertext--ml-multiline-text>
        </div>

        ${failed ? html`
          <groupnotifyuser--ml-contextual-feedback type="error" .visible=${true} .dismissible=${false} .duration=${0}>
            <Title>${this.msg.createErrorTitle}</Title>
            <Message>${this.msg.createErrorMessage}</Message>
          </groupnotifyuser--ml-contextual-feedback>
        ` : ''}

        <div class="sticky bottom-0 -mx-4 mt-6 border-t border-[var(--border-subtle,currentColor)] bg-[var(--surface-bg,transparent)] px-4 py-4">
          <grouptriggeraction--ml-button-standard
            data-variant="primary"
            size="lg"
            data-class="w-full"
            .disabled=${!draft.nome}
            .loading=${submitting}
            @action=${() => this.cmdCriarLista().then(() => {
              if (this.cmdCriarListaStatus === 'success') this.setScenario('listas');
            })}>
            <Label>${this.msg.createList}</Label>
          </grouptriggeraction--ml-button-standard>
        </div>
      </section>
    `;
  }

  private renderEditForm() {
    const draft = this.cmdSalvarListaDraft;
    const selected = this.formularioLista;
    const failed = this.cmdSalvarListaStatus === 'error';
    const submitting = this.cmdSalvarListaStatus === 'loading';
    const changed = draft.nome !== selected?.nome || (draft.details.descricao ?? '') !== (selected?.details.descricao ?? '');

    return html`
      <section data-organism-id="formularioLista" class="flex min-h-full flex-col bg-[var(--page-bg,transparent)] px-4 py-5">
        <div class="flex flex-1 flex-col gap-5">
          <groupentertext--ml-floating-text-input
            data-class="w-full"
            .value=${draft.nome ?? ''}
            .error=${failed ? this.msg.nameError : ''}
            .name=${'nome'}
            .placeholder=${this.msg.namePlaceholder}
            .minLength=${4}
            .maxLength=${null}
            .required=${true}
            .loading=${submitting}
            @input=${(e: CustomEvent<{ value: string }>) => this.setCmdSalvarListaDraft({ ...draft, nome: e.detail.value || null })}>
            <Label>${this.msg.nameLabel}</Label>
            <Helper>${this.msg.nameHelper}</Helper>
          </groupentertext--ml-floating-text-input>

          <groupentertext--ml-multiline-text
            data-class="w-full"
            .value=${draft.details.descricao ?? ''}
            .name=${'descricao'}
            .placeholder=${this.msg.descriptionPlaceholder}
            .rows=${4}
            .maxLength=${null}
            .loading=${submitting}
            @input=${(e: CustomEvent<{ value: string }>) => this.setCmdSalvarListaDraft({ ...draft, details: { ...draft.details, descricao: e.detail.value || null } })}>
            <Label>${this.msg.descriptionLabel}</Label>
            <Helper>${this.msg.descriptionHelper}</Helper>
          </groupentertext--ml-multiline-text>
        </div>

        ${failed ? html`
          <groupnotifyuser--ml-contextual-feedback type="error" .visible=${true} .dismissible=${false} .duration=${0}>
            <Title>${this.msg.saveErrorTitle}</Title>
            <Message>${this.msg.saveErrorMessage}</Message>
          </groupnotifyuser--ml-contextual-feedback>
        ` : ''}

        <div class="sticky bottom-0 -mx-4 mt-6 border-t border-[var(--border-subtle,currentColor)] bg-[var(--surface-bg,transparent)] px-4 py-4">
          <grouptriggeraction--ml-button-standard
            data-variant="primary"
            size="lg"
            data-class="w-full"
            .disabled=${!draft.nome || !changed}
            .loading=${submitting}
            @action=${() => this.cmdSalvarLista().then(() => {
              if (this.cmdSalvarListaStatus === 'success') {
                this.selectListaTarefas(null);
                this.setScenario('listas');
              }
            })}>
            <Label>${this.msg.saveList}</Label>
          </grouptriggeraction--ml-button-standard>
        </div>
      </section>
    `;
  }

  render() {
    this.msg = pageMessages[this.getMessageKey(pageMessages)];
    return html`
      <molecules--ml-scenary-102020
        mode="scenary"
        .value=${this.scenary || (this.selectedListaTarefas !== null ? 'editar' : 'listas')}
        .backLabel=${this.msg.backToLists}
        @change=${(e: CustomEvent<{ value: string }>) => {
          if (e.target === e.currentTarget) {
            this.setScenario(e.detail.value);
            if (e.detail.value === 'listas') this.selectListaTarefas(null);
          }
        }}>
        <Scene value="listas" title=${this.msg.pageTitle}>
          ${this.renderCollection()}
        </Scene>
        <Scene value="nova" title=${this.msg.newListTitle} nav="back" backTo="listas">
          ${this.renderCreateForm()}
        </Scene>
        <Scene value="editar" title=${this.formularioLista?.nome ?? this.msg.newListTitle} nav="back" backTo="listas">
          ${this.renderEditForm()}
        </Scene>
      </molecules--ml-scenary-102020>
    `;
  }
}
